WebLink.url:
{!REQUIRESCRIPT("/soap/ajax/32.0/connection.js")}
{!REQUIRESCRIPT("/soap/ajax/32.0/apex.js")}
{!REQUIRESCRIPT("/support/console/20.0/integration.js")}

var confirmar = confirm("Delete contact?");
if (confirmar){
	try{
	var c = new sforce.SObject("Contact");
	c.id = "{!Contact.Id}";
	c.Logical_Delete__c=true;
	c.OwnerId = "{!$Setup.Application_Settings_Hierarchy__c.System_Admin_ID__c}";
	result = sforce.connection.update([c]);

	if ( result[0].getBoolean( "success" ) ) {

		window.location.reload();

	  } else {
		var errors = result[0].errors;
		var errorMessages = "";

		for ( var i = 0; i < errors.length; i++ ) {
		  errorMessages += errors[i].message + '\n';
		}
		if (errorMessages != ''){
		alert( errorMessages ); // display all validation errors
		}
		else{
		  alert ('Insufficient Privileges');
	   }

	  }
	}catch ( ex ) {

	  alert( ex ); // display any javascript exception message
	}
}
